from __future__ import annotations

import json
import os
import uuid
from copy import deepcopy
from datetime import datetime, timezone
from pathlib import Path
from threading import RLock
from typing import Any, Dict, List, Optional

from cryptography.fernet import Fernet, InvalidToken
from fastapi import APIRouter, HTTPException, Query
from pydantic import BaseModel, Field


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _dump(model: BaseModel) -> Dict[str, Any]:
    if hasattr(model, "model_dump"):
        return model.model_dump(exclude_none=True)
    return model.dict(exclude_none=True)


class AccountCreate(BaseModel):
    platform: str = Field(..., min_length=1, description="平台名，如 douyin/kuaishou/taobao")
    account_name: str = Field(..., min_length=1)
    cookie: str = ""
    login_status: str = "offline"
    expires_at: Optional[str] = None
    note: str = ""
    meta: Dict[str, Any] = Field(default_factory=dict)


class AccountUpdate(BaseModel):
    platform: Optional[str] = None
    account_name: Optional[str] = None
    cookie: Optional[str] = None
    login_status: Optional[str] = None
    expires_at: Optional[str] = None
    note: Optional[str] = None
    meta: Optional[Dict[str, Any]] = None


class StatusUpdate(BaseModel):
    status: str = Field(..., description="online/offline/limited/banned")
    reason: str = ""
    meta: Dict[str, Any] = Field(default_factory=dict)


class CookieVault:
    def __init__(self, key_path: Optional[Path] = None):
        env_key = os.getenv("PHS_ACCOUNT_FERNET_KEY")
        self.key_path = key_path or Path("data") / "multi_account" / "fernet.key"
        if env_key:
            key = env_key.encode("utf-8")
        else:
            self.key_path.parent.mkdir(parents=True, exist_ok=True)
            if self.key_path.exists():
                key = self.key_path.read_bytes().strip()
            else:
                key = Fernet.generate_key()
                self.key_path.write_bytes(key)
        self.fernet = Fernet(key)

    def encrypt(self, cookie: str) -> str:
        if not cookie:
            return ""
        return self.fernet.encrypt(cookie.encode("utf-8")).decode("utf-8")

    def decrypt(self, token: str) -> str:
        if not token:
            return ""
        try:
            return self.fernet.decrypt(token.encode("utf-8")).decode("utf-8")
        except InvalidToken:
            return ""


class AccountStore:
    valid_status = {"online", "offline", "limited", "banned"}

    def __init__(self, path: Optional[str] = None):
        default_path = Path("data") / "multi_account" / "accounts.json"
        self.path = Path(path or os.getenv("PHS_MULTI_ACCOUNT_DB", default_path))
        self.lock = RLock()
        self.vault = CookieVault(self.path.parent / "fernet.key")
        self.data: Dict[str, Any] = {"accounts": [], "status_events": []}
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._load()

    def _load(self) -> None:
        if not self.path.exists():
            self._save()
            return
        try:
            self.data = json.loads(self.path.read_text(encoding="utf-8"))
            self.data.setdefault("accounts", [])
            self.data.setdefault("status_events", [])
        except Exception:
            self.path.replace(self.path.with_suffix(".corrupt.json"))
            self.data = {"accounts": [], "status_events": []}
            self._save()

    def _save(self) -> None:
        tmp = self.path.with_suffix(".tmp")
        tmp.write_text(json.dumps(self.data, ensure_ascii=False, indent=2), encoding="utf-8")
        tmp.replace(self.path)

    def _find_index(self, account_id: str) -> int:
        for i, item in enumerate(self.data["accounts"]):
            if item.get("id") == account_id:
                return i
        return -1

    def _public(self, item: Dict[str, Any], include_cookie: bool = False) -> Dict[str, Any]:
        out = deepcopy(item)
        cipher = out.pop("cookie_cipher", "")
        out["has_cookie"] = bool(cipher)
        if include_cookie:
            out["cookie"] = self.vault.decrypt(cipher)
        return out

    def _normalize_status(self, status: str) -> str:
        value = (status or "offline").strip().lower()
        if value not in self.valid_status:
            raise ValueError(f"invalid status: {value}")
        return value

    def list(self, platform: Optional[str] = None, status: Optional[str] = None) -> List[Dict[str, Any]]:
        with self.lock:
            items = [self._public(x) for x in self.data["accounts"]]
        if platform:
            items = [x for x in items if x.get("platform") == platform]
        if status:
            items = [x for x in items if x.get("login_status") == status]
        return sorted(items, key=lambda x: x.get("updated_at", ""), reverse=True)

    def get(self, account_id: str, include_cookie: bool = False) -> Dict[str, Any]:
        with self.lock:
            idx = self._find_index(account_id)
            if idx < 0:
                raise KeyError(account_id)
            return self._public(self.data["accounts"][idx], include_cookie=include_cookie)

    def create(self, payload: AccountCreate) -> Dict[str, Any]:
        item = _dump(payload)
        cookie = item.pop("cookie", "")
        item["id"] = uuid.uuid4().hex
        item["login_status"] = self._normalize_status(item.get("login_status", "offline"))
        item["cookie_cipher"] = self.vault.encrypt(cookie)
        item["created_at"] = _now()
        item["updated_at"] = item["created_at"]
        with self.lock:
            self.data["accounts"].append(item)
            self._save()
            return self._public(item)

    def update(self, account_id: str, payload: AccountUpdate) -> Dict[str, Any]:
        patch = _dump(payload)
        with self.lock:
            idx = self._find_index(account_id)
            if idx < 0:
                raise KeyError(account_id)
            item = self.data["accounts"][idx]
            if "login_status" in patch:
                patch["login_status"] = self._normalize_status(patch["login_status"])
            if "cookie" in patch:
                item["cookie_cipher"] = self.vault.encrypt(patch.pop("cookie") or "")
            item.update(patch)
            item["updated_at"] = _now()
            self._save()
            return self._public(item)

    def delete(self, account_id: str) -> Dict[str, Any]:
        with self.lock:
            idx = self._find_index(account_id)
            if idx < 0:
                raise KeyError(account_id)
            item = self.data["accounts"].pop(idx)
            self.data["status_events"] = [x for x in self.data["status_events"] if x.get("account_id") != account_id]
            self._save()
            return self._public(item)


class SessionManager:
    def __init__(self, store: AccountStore):
        self.store = store

    def get_status(self, account_id: str) -> Dict[str, Any]:
        account = self.store.get(account_id)
        return {
            "account_id": account_id,
            "platform": account.get("platform"),
            "account_name": account.get("account_name"),
            "status": account.get("login_status", "offline"),
            "expires_at": account.get("expires_at"),
            "updated_at": account.get("updated_at"),
        }

    def set_status(self, account_id: str, payload: StatusUpdate) -> Dict[str, Any]:
        status = self.store._normalize_status(payload.status)
        account = self.store.update(account_id, AccountUpdate(login_status=status))
        event = {
            "id": uuid.uuid4().hex,
            "account_id": account_id,
            "status": status,
            "reason": payload.reason,
            "meta": payload.meta,
            "created_at": _now(),
        }
        with self.store.lock:
            self.store.data["status_events"].append(event)
            self.store.data["status_events"] = self.store.data["status_events"][-1000:]
            self.store._save()
        return {"account": account, "event": event}


def create_multi_account_router(store: Optional[AccountStore] = None, prefix: str = "") -> APIRouter:
    db = store or AccountStore()
    sessions = SessionManager(db)
    router = APIRouter(prefix=prefix, tags=["multi-account"])

    @router.get("/accounts")
    def list_accounts(platform: Optional[str] = None, status: Optional[str] = None) -> Dict[str, Any]:
        items = db.list(platform=platform, status=status)
        return {"items": items, "count": len(items)}

    @router.post("/accounts")
    def create_account(payload: AccountCreate) -> Dict[str, Any]:
        try:
            return db.create(payload)
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc))

    @router.get("/accounts/{account_id}")
    def get_account(account_id: str, include_cookie: bool = Query(default=False)) -> Dict[str, Any]:
        try:
            return db.get(account_id, include_cookie=include_cookie)
        except KeyError:
            raise HTTPException(status_code=404, detail="account not found")

    @router.put("/accounts/{account_id}")
    def update_account(account_id: str, payload: AccountUpdate) -> Dict[str, Any]:
        try:
            return db.update(account_id, payload)
        except KeyError:
            raise HTTPException(status_code=404, detail="account not found")
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc))

    @router.delete("/accounts/{account_id}")
    def delete_account(account_id: str) -> Dict[str, Any]:
        try:
            return {"deleted": True, "item": db.delete(account_id)}
        except KeyError:
            raise HTTPException(status_code=404, detail="account not found")

    @router.get("/accounts/{account_id}/status")
    def get_account_status(account_id: str) -> Dict[str, Any]:
        try:
            return sessions.get_status(account_id)
        except KeyError:
            raise HTTPException(status_code=404, detail="account not found")

    @router.put("/accounts/{account_id}/status")
    def set_account_status(account_id: str, payload: StatusUpdate) -> Dict[str, Any]:
        try:
            return sessions.set_status(account_id, payload)
        except KeyError:
            raise HTTPException(status_code=404, detail="account not found")
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc))

    return router


class MultiAccountManagerProvider:
    provider_id = "multi_account"
    name = "Multi Account Manager"
    version = "0.1.0"

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        self.store = AccountStore(self.config.get("db_path"))
        self.sessions = SessionManager(self.store)
        self.router = create_multi_account_router(self.store)

    def get_router(self) -> APIRouter:
        return self.router

    def health(self) -> Dict[str, Any]:
        return {
            "provider": self.provider_id,
            "ok": True,
            "db_path": str(self.store.path),
            "account_count": len(self.store.data.get("accounts", [])),
        }

    def metadata(self) -> Dict[str, Any]:
        return {
            "id": self.provider_id,
            "name": self.name,
            "version": self.version,
            "routes": ["/accounts", "/accounts/{id}/status"],
        }


def create_provider(config: Optional[Dict[str, Any]] = None) -> MultiAccountManagerProvider:
    return MultiAccountManagerProvider(config)


provider = MultiAccountManagerProvider()
